class AcquisitionDoubleProjectionTest {
    private fun state(value: Double) = StoredCharacter(
        DublCharacter("hero", gear=CharacterGear(loadManual=value,items=listOf(GearItem("item",load=value)))),
        CharacterSheetExtras(),emptyList(),Ledger(Opening("opening","source",Amount(100,0),RequirementNode.CreationPhase.Phase.Creating,OpeningProvenance.NewCharacter),emptyList()),
        emptyList(),emptyList(),SyncMetadata(0),0,0,RequirementNode.CreationPhase.Phase.Creating)
    private fun token(raw:String):String {
        val root=JsonReader(raw,strict=true).read() as JsonValue.Obj
        val snapshot=root.values.getValue("characterSnapshot") as JsonValue.Obj
        val character=(snapshot.values.getValue("characters") as JsonValue.Arr).values.single() as JsonValue.Obj
        return (((character.values.getValue("gear") as JsonValue.Obj).values.getValue("loadManual")) as JsonValue.Num).raw
    }
    private fun historical(value:Double,rawToken:String):String {
        val raw=encodeSyncEnvelope(state(value))
        val root=JsonReader(raw,strict=true).read() as JsonValue.Obj
        val snap=root.values.getValue("characterSnapshot") as JsonValue.Obj
        val c=(snap.values.getValue("characters") as JsonValue.Arr).values.single() as JsonValue.Obj
        val gear=c.values.getValue("gear") as JsonValue.Obj
        val item=(gear.values.getValue("items") as JsonValue.Arr).values.single() as JsonValue.Obj
        val changed=JsonValue.Obj(gear.values+mapOf("loadManual" to JsonValue.Num(rawToken),"items" to jsonArray(listOf(JsonValue.Obj(item.values+("load" to JsonValue.Num(rawToken)))))))
        val changedCharacter=JsonValue.Obj(c.values+("gear" to changed))
        val changedSnapshot=JsonValue.Obj(snap.values+("characters" to jsonArray(listOf(changedCharacter))))
        return canonicalJson(jsonStringify(JsonValue.Obj(root.values+("characterSnapshot" to changedSnapshot))))
    }
