    @Test fun valid_old_leaf_tokens_survive_local_wire_copy_and_bare_patch() {
        val raw=historical(0.1,"1e-1")
        val old=decodeSyncEnvelope(raw)
        assertEquals(raw,encodeSyncEnvelope(old))
        assertEquals("1e-1",token(encodeEnvelope(old)))
        assertEquals("1e-1",token(encodeSyncEnvelope(old.copy(character=old.character.copy(name="edited")))))
        assertEquals("1e-1",token(encodeSyncEnvelope(copyAcquisitionCharacter(old,"copied","import"))))
        val patch=CharacterPatch(old.character.copy(hpCurrent=1))
        assertEquals("1e-1",token(encodeEnvelope(patch.apply(old))))
    }
    @Test fun changed_bits_are_discarded_and_change_back_cannot_resurrect_old_token() {
        val old=decodeSyncEnvelope(historical(0.1,"1e-1"))
        val changed=old.copy(character=old.character.copy(gear=old.character.gear.copy(loadManual=0.125)))
        val back=changed.copy(character=changed.character.copy(gear=changed.character.gear.copy(loadManual=0.1)))
        assertNotEquals("1e-1",token(encodeSyncEnvelope(back)))
        val patch=CharacterPatch(changed.character)
        val captured=patch.apply(changed)
        assertNotEquals("1e-1",token(encodeSyncEnvelope(captured.copy(character=captured.character.copy(gear=captured.character.gear.copy(loadManual=0.1))))))
    }
    @Test fun unknown_fields_nonfinite_underflow_and_normalized_integers_stay_refused() {
        val raw=historical(0.1,"1e-1")
        assertFails { decodeSyncEnvelope(raw.replace("\"loadManual\":1e-1","\"loadManual\":1e999")) }
        assertFails { decodeSyncEnvelope(raw.replace("\"loadManual\":1e-1","\"loadManual\":1e-999")) }
        assertFails { decodeSyncEnvelope(raw.replace("\"loadManual\":1e-1","\"extra\":1,\"loadManual\":1e-1")) }
        assertFails { decodeSyncEnvelope(raw.replace("\"size\":5","\"size\":5.0")) }
    }
    @Test fun legacy_serializer_remains_platform_native_and_evidence_is_not_gameplay_equality() {
        val original=state(0.1)
        val decoded=decodeSyncEnvelope(historical(0.1,"1e-1"))
        assertEquals(original.character.gear,decoded.character.gear)
        assertEquals(original.character.gear.hashCode(),decoded.character.gear.hashCode())
        assertEquals(SnapshotCodec.encode(AppSnapshot(listOf(original.character),"hero")),SnapshotCodec.encode(AppSnapshot(listOf(decoded.character),"hero")))
        val (automatic,load,items)=decoded.character.gear
        assertTrue(automatic);assertEquals(0.1,load);assertEquals("item",items.single().uid)
    }
    private fun run(block:suspend ()->Unit) {
        var result:Result<Unit>?=null
        block.startCoroutine(object:Continuation<Unit> { override val context=EmptyCoroutineContext;override fun resumeWith(value:Result<Unit>) { result=value } })
        checkNotNull(result).getOrThrow()
    }
    @Test fun detached_mutation_undo_and_mementos_preserve_historical_tokens()=run {
        val initial=decodeSyncEnvelope(historical(0.1,"1e-1"))
        val store=InMemoryAcquisitionStore(mapOf("hero" to encodeEnvelope(initial)))
        val coordinator=CharacterMutationCoordinator(store,{AcquisitionCatalog(emptyMap(),"synthetic","synthetic")},{"unused"})
        val staged=coordinator.prepareNonFinancial("edit","hero",0) { character.setName("renamed") }
        val command=CanonicalMutation("edit","hero",0,
            MutationPayload.ManualCorrection((staged.payload as MutationPayload.NonFinancial).characterPatch,Amount.ZERO),"Explicit correction, unchanged funding")
        assertIs<MutationResult.Applied>(coordinator.mutate(command))
        val after=(store.load("hero") as LoadResult.Loaded).state
        assertEquals("1e-1",token(encodeSyncEnvelope(after)))
        assertTrue(after.ledger.entries.single().evidenceCanonical.contains("\"loadManual\":1e-1"))
        assertEquals(encodeSyncEnvelope(after),after.outbox.single().payloadCanonical)
        val restarted=InMemoryAcquisitionStore(mapOf("hero" to encodeEnvelope(after)))
        assertIs<ApplyResult.Applied>(AcquisitionUndo(restarted).undo("hero","undo",1))
        val undone=(restarted.load("hero") as LoadResult.Loaded).state
        assertEquals("1e-1",token(encodeSyncEnvelope(undone)))
        assertEquals(initial.character.name,undone.character.name)
        assertEquals(encodeEnvelope(undone),encodeEnvelope((decodeEnvelope(encodeEnvelope(undone)) as LoadResult.Loaded).state))
    }
    @Test fun item_uid_leaf_kind_and_signed_zero_changes_discard_stale_capsules() {
        val initial=decodeSyncEnvelope(historical(0.1,"1e-1"))
        val item=initial.character.gear.items.single()
        val renamed=initial.copy(character=initial.character.copy(gear=initial.character.gear.copy(items=listOf(item.copy(uid="new")))))
        val changedBack=renamed.copy(character=renamed.character.copy(gear=renamed.character.gear.copy(items=listOf(renamed.character.gear.items.single().copy(uid="item")))))
        assertFalse(encodeSyncEnvelope(changedBack).contains("\"load\":1e-1"))
        val wrongLeaf=initial.copy(character=initial.character.copy(gear=initial.character.gear.copy(items=listOf(item.copy(acquisitionLoadToken=initial.character.gear.acquisitionLoadToken)))))
        assertFalse(encodeSyncEnvelope(wrongLeaf).contains("\"load\":1e-1"))
        val oldZero=decodeSyncEnvelope(historical(-0.0,"-0e0"))
        val zero=oldZero.copy(character=oldZero.character.copy(gear=oldZero.character.gear.copy(loadManual=0.0)))
        val negativeAgain=zero.copy(character=zero.character.copy(gear=zero.character.gear.copy(loadManual=-0.0)))
        assertEquals("-0.0",token(encodeSyncEnvelope(negativeAgain)))
    }

